def Frame.TreeUnravelling (F : Frame) (r : F.World) : Kripke.Frame where
  World := { c : List F.World | [r] <+: c ∧ c.Chain' F.Rel }
  Rel cx cy := ∃ z, cx.1 ++ [z] = cy.1
  world_nonempty := ⟨[r], (by simp)⟩

